@staticmethod
def _substring_occurrences(
    in_str: str, substrings: Iterable[str]
) -> Dict[str, List[int]]:
    """Find every occurrence of the given substrings."""
    occurrences = {}
    for substring in substrings:
        occurrences[substring] = list(findall(substring, in_str))
    return occurrences

@staticmethod
def _sorted_occurrence_tuples(
    occurrences: Dict[str, List[int]],
) -> List[Tuple[str, int]]:
    """Sort a dict of occurrences into a sorted list of tuples."""
    return sorted(
        ((raw, idx) for raw in occurrences.keys() for idx in occurrences[raw]),
        # Sort first by position, then by lexical (for stability)
        key=lambda x: (x[1], x[0]),
    )

@staticmethod
def _filter_occurrences(
    in_slice: slice, occurrences: Dict[str, List[int]]
) -> Dict[str, List[int]]:
    """Filter a dict of occurrences to just those within a slice."""
    filtered = {
        key: [
            pos
            for pos in occurrences[key]
            if in_slice.start <= pos < in_slice.stop
        ]
        for key in occurrences.keys()
    }
    # Only keep keys which have remaining occurrences.
    return {key: filtered[key] for key in filtered.keys() if filtered[key]}

@classmethod
def _split_invariants(
    cls,
    raw_sliced: List[RawFileSlice],
    literals: List[str],
    raw_occurrences: Dict[str, List[int]],
    templated_occurrences: Dict[str, List[int]],
    templated_str: str,
) -> Iterator[IntermediateFileSlice]:
    """Split a sliced file on its invariant literals."""
    # Calculate invariants
    invariants = [
        literal
        for literal in literals
        if len(raw_occurrences[literal]) == 1
        and len(templated_occurrences[literal]) == 1
    ]
    templater_logger.debug("    Invariants: %s", invariants)
    # A map of the invariants to their index in the templated string.
    invariant_templ_idx = {
        literal: templated_occurrences[literal][0] for literal in invariants
    }

    # Set up some buffers
    buffer: List[RawFileSlice] = []
    idx: Optional[int] = None
    templ_idx = 0

    for raw_slice in raw_sliced:
        # If we haven't started a buffer yet, record the starting index.
        if idx is None:
            idx = raw_slice.source_idx
        # Is this slice an invariant literal?
        if raw_slice.slice_type == "literal" and raw_slice.raw in invariants:
            # Yield anything in the buffer first.
            if buffer:
                yield IntermediateFileSlice(
                    "simple" if len(buffer) == 1 else "compound",
                    slice(idx, raw_slice.source_idx),
                    slice(templ_idx, invariant_templ_idx[raw_slice.raw]),
                    buffer,
                )
                buffer = []
            # Yield the invariant itself.
            templ_idx = invariant_templ_idx[raw_slice.raw] + len(raw_slice.raw)
            yield IntermediateFileSlice(
                "invariant",
                slice(
                    raw_slice.source_idx,
                    raw_slice.source_idx + len(raw_slice.raw),
                ),
                slice(invariant_templ_idx[raw_slice.raw], templ_idx),
                [raw_slice],
            )
            idx = None
        else:
            # Not an invariant, add it to the buffer.
            buffer.append(raw_slice)

    # If there's anything left in the buffer, yield it.
    if buffer:
        assert idx is not None
        yield IntermediateFileSlice(
            "simple" if len(buffer) == 1 else "compound",
            slice(idx, buffer[-1].source_idx + len(buffer[-1].raw)),
            slice(templ_idx, len(templated_str)),
            buffer,
        )
